import pathlib,json,subprocess
P=pathlib.Path('/opt/metrolabs/qa/sgo-ponto-mobile-20261104');OLD='sha256:fa1e066352d2d6f70ba966f0e1290eae094e41e2572512555fc6bdb5eb8c7169';NEW=json.loads((P/'build-result.json').read_text())['image'];assert not(P/'image-byte-comparison.json').exists()
node=r"""const fs=require('fs'),path=require('path'),{createHash}=require('crypto');const out={};function walk(p){for(const n of fs.readdirSync(p).sort()){const f=path.join(p,n),s=fs.lstatSync(f);if(s.isDirectory())walk(f);else if(s.isFile())out[f]=createHash('sha256').update(fs.readFileSync(f)).digest('hex');}}for(const p of ['/app/dist','/app/src','/app/scripts','/app/legado','/app/legado_command','/app/legado_modelos'])walk(p);for(const p of ['/app/package.json','/app/package-lock.json','/app/tsconfig.json'])out[p]=createHash('sha256').update(fs.readFileSync(p)).digest('hex');console.log(JSON.stringify(out));"""
