r={'passed':True,'oldImage':OLD,'newImage':NEW,'filesCompared':len(a),'changedFiles':changes,'allBackendCoreCommandModelsBytesPreserved':True};(P/'image-byte-comparison.json').write_text(json.dumps(r,indent=2));print(json.dumps(r))
